table(['File / location','Responsibility aur useful entry point'],[['src/client/src/app/encrypted-transport.ts','connect/createSession: ECDH + HKDF.<br/>encrypt/decrypt: AES-GCM, tag split/join.<br/>post: complete encrypted HTTP round trip.'],['src/Demo.Api/Transport/SessionStore.cs','Create: session keys/expiry.<br/>Process: decrypt, replay check, handler run, encrypt result.<br/>Echo: Process ka demo wrapper.'],['src/Demo.Api/Auth/AuthStore.cs','Handle: auth operation dispatch.<br/>Register/LoginUser: validation/hash verification.<br/>Token lookup, expiry, lockout, logout.'],['src/Demo.Api/Program.cs','Services register karta hai; health, crypto, echo aur auth routes map karta hai.'],['src/Demo.Gateway/Program.cs','Allowed routes check; request/response forward; timeout aur unavailable backend handle karta hai.'],['src/client/src/app/auth.service.ts','register/login/profile/logout calls; memory-only token aur user signal.'],['src/client/src/app/auth-page.ts + auth-page.html + auth-page.css','Login/register form, confirmation, submission status aur styling.'],['src/client/src/app/profile.ts','Protected profile verify karna aur logout.'],['src/client/src/app/app.routes.ts','login/register/profile/lab routes; profile navigation guard.'],['src/client/src/app/app.ts + app.html + app.css','App shell aur navigation.'],['src/client/src/app/lab.ts + lab.html + lab.css','Encrypted echo screen aur synthetic wire-payload debug panels.'],['src/client/proxy.conf.json','Development mein /api/** ko gateway:5100 par bhejta hai.'],['scripts/verify-transport.mjs + verify-auth.mjs','Real Web Crypto/.NET integration, tamper/replay aur authentication checks.']],[232,253])
