table(['Symptom','Likely reason / action'],[['Connection failed / HTTP 502','API:5200 aur gateway:5100 running hain? ApiBaseUrl sahi hai?'],['HTTP 504','Backend gateway ke 10-second timeout ke andar respond nahi kar raha. API logs dekho.'],['HTTP 404 on new route','Gateway allowlist aur API route exact match karo.'],['HTTP 400 / decrypt failed','Nonce/tag size, ciphertext, AES key, AAD route/direction aur HKDF labels match karo. Envelope edit hua ho toh reject expected hai.'],['HTTP 409','Unknown/expired crypto session, replayed request ID ya request capacity. API restart hua ho toh browser refresh karke login dobara karo.'],['Login refresh ke baad gaya','Expected: browser token memory-only hai. Dobara login karo.'],['Registered account missing','API restart ne in-memory users clear kiye. Dobara register karo.'],['ok:false / too many attempts','Register/login ka global 60 attempts/minute budget. Minute wait karo. Five wrong passwords se account one minute locked hota hai.'],['Build file locked','Running API/gateway apne terminals mein Ctrl+C se stop karo; build, phir restart karo.']],[170,315])
